args.content:
// Minimal re-implementation of Python's argparse for this exact spec:
//
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True)
//
// Replicates the observed behavior of CPython 3.12 argparse byte-for-byte:
//   - prog name is fixed to "test16_executable" (as the reference binary reports)
//   - supports "--a value", "--a=value", and unambiguous long-option
//     abbreviations (e.g. "--he" -> "--help")
//   - "-h" / "--help" print the help text to stdout and exit 0
//   - the last occurrence of "--a" wins
//   - a token starting with "-" is not consumed as the value of "--a",
//     unless it is exactly "-" or looks like a negative number
//     (argparse's _negative_number_matcher)
//   - "--" and everything after it are treated as unrecognized extras
//     (Python 3.12 behavior when the parser has no positional arguments)
//   - error precedence: consumption errors > missing required > unrecognized
//   - errors print usage + message to stderr and exit 2

const PROG = 'test16_executable';

const USAGE = `usage: ${PROG} [-h] --a A\n`;

const HELP =
  USAGE +
  '\n' +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n';

// argparse._negative_number_matcher
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function printHelpAndExit() {
  process.stdout.write(HELP);
  process.exit(0);
}

function errorAndExit(message) {
  process.stderr.write(USAGE);
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

// An option-like token cannot be swallowed as the value of "--a".
function looksLikeOption(token) {
  if (token.length === 0 || token[0] !== '-') return false;
  if (token === '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return true;
}

// Resolve a long option name (without any "=value" part) to its canonical
// form, allowing unambiguous abbreviations like argparse does.
// Returns '--help', '--a', or null when unknown.
function matchLongOption(name) {
  if (name === '--help' || name === '--a') return name;
  const candidates = ['--help', '--a'].filter((opt) => opt.startsWith(name));
  if (candidates.length === 1) return candidates[0];
  return null;
}

// Parse argv (defaults to process.argv.slice(2)) and return { a: <string> }.
// Exits the process directly on help (0) or any argument error (2),
// exactly like argparse does.
export function parseArgs(argv = process.argv.slice(2)) {
  const extras = [];
  let a = null;
  let seenA = false;

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    // "--" and everything after it become extras (no positionals defined).
    if (token === '--') {
      for (; i < argv.length; i++) extras.push(argv[i]);
      break;
    }

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const inlineValue = eq === -1 ? null : token.slice(eq + 1);
      const canonical = matchLongOption(name);

      if (canonical === '--help') {
        if (inlineValue !== null) {
          errorAndExit(
            `argument -h/--help: ignored explicit argument '${inlineValue}'`,
          );
        }
        printHelpAndExit();
      } else if (canonical === '--a') {
        if (inlineValue !== null) {
          a = inlineValue;
          seenA = true;
        } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1])) {
          a = argv[i + 1];
          seenA = true;
          i++;
        } else {
          errorAndExit('argument --a: expected one argument');
        }
      } else {
        // Unknown long option: collected as an extra, reported later.
        extras.push(token);
      }
    } else if (token === '-h') {
      printHelpAndExit();
    } else {
      // Unknown short option or stray positional: extra.
      extras.push(token);
    }
  }

  // argparse checks required arguments before reporting unrecognized ones.
  if (!seenA) {
    errorAndExit('the following arguments are required: --a');
  }
  if (extras.length > 0) {
    errorAndExit(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a };
}

