args.content:
// Entry point: Node.js port of
//
//   import yaml, argparse
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True)
//   args = parser.parse_args()
//   result = yaml.dump(yaml.safe_load(args.a), Dumper=yaml.SafeDumper)
//   print(result)
//
// safeDump() reproduces PyYAML's dump output, which already ends with a
// newline; the extra '\n' appended here mirrors Python's print().

import { parseArgs } from './argparse.mjs';
import { safeLoad } from './yaml/loader.mjs';
import { safeDump } from './yaml/dumper.mjs';

const args = parseArgs();

let result;
try {
  result = safeDump(safeLoad(args.a));
} catch (err) {
  // Python prints a traceback and exits 1 on YAML errors; matching the
  // exact traceback text is not required, only the exit code.
  const message = err && err.message ? err.message : String(err);
  process.stderr.write(message + '\n');
  process.exit(1);
}

process.stdout.write(result + '\n');

