mkdir -p /tmp/t16/yaml && cp /output/test16.mjs /tmp/t16/ && cp /output/argparse.mjs /tmp/t16/ && cp /output/yaml/types.mjs /tmp/t16/yaml/
cat > /tmp/t16/yaml/loader.mjs <<'EOF'
export function safeLoad(text) {
  if (text === 'BAD') throw new Error('mock yaml error');
  return text;
}
EOF
cat > /tmp/t16/yaml/dumper.mjs <<'EOF'
export function safeDump(value) { return 'DUMPED<' + value + '>\n'; }
EOF
node /tmp/t16/test16.mjs --a 'hello' | od -c
node /tmp/t16/test16.mjs --a BAD; echo "exit=$?"
node /tmp/t16/test16.mjs --help >/dev/null; echo "help exit=$?"
node /tmp/t16/test16.mjs 2>/dev/null; echo "noargs exit=$?"
rm -rf /tmp/t16

