args.command:
chmod +x /output/tests/compare.sh
# Sanity: count cases and show a few reconstructed ones exactly as the harness will pass them
node -e '
const fs = require("fs");
const text = fs.readFileSync("/output/tests/cases.txt", "utf8");
const lines = text.split("\n");
if (lines[lines.length-1] === "") lines.pop();
const cases = []; let cur = [];
for (const l of lines) {
  if (l === "===") { if (cur.length) cases.push(cur); cur = []; }
  else cur.push(l);
}
if (cur.length) cases.push(cur);
console.log("total cases:", cases.length);
const show = i => console.log(i, JSON.stringify(cases[i].join("\n")));
[0, 48, 49, 69, 71, 72, 80, 91, 92, cases.length-2, cases.length-1].forEach(show);
// check for argparse-problematic single tokens starting with "-"
cases.forEach((c, i) => {
  const s = c.join("\n");
  if (s.startsWith("-") && !s.includes(" ") && !/^-\d/.test(s)) console.log("ARGPARSE RISK:", i, JSON.stringify(s));
});'

