// Error types mirroring PyYAML's error hierarchy (yaml.error / yaml.scanner /
// yaml.parser / yaml.composer / yaml.constructor). The messages resemble
// PyYAML's but are not required to match byte-for-byte; the entry point just
// needs a thrown Error to exit 1.

// A position in the input stream, able to render a PyYAML-style snippet.
export class Mark {
  constructor(buffer, index, line, column) {
    this.buffer = buffer; // full source string
    this.index = index;   // 0-based character offset
    this.line = line;     // 0-based line number
    this.column = column; // 0-based column number
  }

  // Port of PyYAML's Mark.get_snippet().
  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer == null) return null;
    const buffer = this.buffer;
    let head = '';
    let start = this.index;
    const isBreak = (ch) =>
      ch === '\0' || ch === '\r' || ch === '\n' || ch === '' ||
      ch === ' ' || ch === ' ' || ch === undefined;
    while (start > 0 && !isBreak(buffer[start - 1])) {
      start -= 1;
      if (this.index - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.index;
    while (end < buffer.length && !isBreak(buffer[end])) {
      end += 1;
      if (end - this.index > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = buffer.slice(start, end);
    return ' '.repeat(indent) + head + snippet + tail + '\n' +
      ' '.repeat(indent + this.index - start + head.length) + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "<unicode string>", line ${this.line + 1}, column ${this.column + 1}:`;
    if (snippet) where += '\n' + snippet;
    return where;
  }
}

// Equivalent of PyYAML's MarkedYAMLError.
export class YAMLError extends Error {
  constructor(context, contextMark, problem, problemMark, note) {
    const lines = [];
    if (context != null) lines.push(context);
    if (contextMark != null &&
        (problem == null || problemMark == null ||
         contextMark.line !== problemMark.line ||
         contextMark.column !== problemMark.column)) {
      lines.push(String(contextMark));
    }
    if (problem != null) lines.push(problem);
    if (problemMark != null) lines.push(String(problemMark));
    if (note != null) lines.push(note);
    super(lines.join('\n'));
    this.context = context;
    this.contextMark = contextMark;
    this.problem = problem;
    this.problemMark = problemMark;
    this.note = note;
  }
}

export class ReaderError extends YAMLError {
  constructor(position, character, problem) {
    const code = typeof character === 'number' ? character : character.codePointAt(0);
    const hex = code.toString(16).padStart(4, '0');
    super(null, null,
      `unacceptable character #x${hex}: ${problem}\n  in "<unicode string>", position ${position}`,
      null);
    this.name = 'ReaderError';
  }
}

export class ScannerError extends YAMLError {
  constructor(context, contextMark, problem, problemMark) {
    super(context, contextMark, problem, problemMark);
    this.name = 'ScannerError';
  }
}

export class ParserError extends YAMLError {
  constructor(context, contextMark, problem, problemMark) {
    super(context, contextMark, problem, problemMark);
    this.name = 'ParserError';
  }
}

export class ComposerError extends YAMLError {
  constructor(context, contextMark, problem, problemMark) {
    super(context, contextMark, problem, problemMark);
    this.name = 'ComposerError';
  }
}

export class ConstructorError extends YAMLError {
  constructor(context, contextMark, problem, problemMark) {
    super(context, contextMark, problem, problemMark);
    this.name = 'ConstructorError';
  }
}

