  'const NON_PRINTABLE = /[^\\\\x09\\\\x0A\\\\x0D\\\\x20-\\\\x7E\\\\x85\\\\xA0-\\\\uD7FF\\\\uE000-\\\\uFFFD\\\\u{10000}-\\\\u{10FFFF}]/u;');
fs.writeFileSync('scanner.mjs', s);
