s.split('\n').forEach((l, i) => {
  for (const ch of l) {
    const c = ch.codePointAt(0);
    if ((c < 32 && ch !== '\t') || c === 0x85 || c === 0x2028 || c === 0x2029 || c === 0xFEFF) { bad.push(i + 1); break; }
  }
});
console.log('remaining bad lines:', JSON.stringify(bad));
