  constructor(scanner) {
    this.tokens = scanner.tokens;
    this.pos = 0;
    this.currentEvent = null;
    this.states = [];
    this.marks = [];
    this.state = () => this.parseStreamStart();
    this.yamlVersion = null;
    this.tagHandles = { ...DEFAULT_TAGS };
  }

  // ------------------------------------------------------------------
  // Token / event access
  // ------------------------------------------------------------------

  checkToken(...types) {
    const token = this.tokens[this.pos];
    if (!token) return false;
    if (types.length === 0) return true;
    return types.includes(token.type);
  }

  peekToken() {
    return this.tokens[this.pos];
  }

  getToken() {
    return this.tokens[this.pos++];
  }

  checkEvent(...types) {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state();
    }
    if (this.currentEvent !== null) {
      if (types.length === 0) return true;
      return types.includes(this.currentEvent.type);
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state();
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state) {
      this.currentEvent = this.state();
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  // ------------------------------------------------------------------
  // Grammar states
  // ------------------------------------------------------------------

  // stream ::= STREAM-START implicit_document? explicit_document* STREAM-END
  parseStreamStart() {
    const token = this.getToken();
    const ev = event('stream-start', { startMark: token.startMark, endMark: token.endMark });
    this.state = () => this.parseImplicitDocumentStart();
    return ev;
  }

  // implicit_document ::= block_node DOCUMENT-END*
  parseImplicitDocumentStart() {
    if (!this.checkToken('directive', 'document-start', 'stream-end')) {
      this.tagHandles = { ...DEFAULT_TAGS };
      const token = this.peekToken();
      const ev = event('document-start', {
        startMark: token.startMark, endMark: token.startMark,
        explicit: false, version: null, tags: null,
      });
      this.states.push(() => this.parseDocumentEnd());
      this.state = () => this.parseNode(true, false);
      return ev;
    }
    return this.parseDocumentStart();
  }

  // explicit_document ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
  parseDocumentStart() {
    // Parse any extra document end indicators.
    while (this.checkToken('document-end')) {
      this.getToken();
    }
    // Parse an explicit document.
    if (!this.checkToken('stream-end')) {
      const token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken('document-start')) {
        throw new ParserError(null, null,
          `expected '<document start>', but found '${this.peekToken().id}'`,
          this.peekToken().startMark);
      }
      const endToken = this.getToken();
      const ev = event('document-start', {
        startMark, endMark: endToken.endMark,
        explicit: true, version, tags,
      });
      this.states.push(() => this.parseDocumentEnd());
      this.state = () => this.parseDocumentContent();
      return ev;
    }
    // Parse the end of the stream.
    const token = this.getToken();
    const ev = event('stream-end', { startMark: token.startMark, endMark: token.endMark });
    this.states = [];
    this.marks = [];
    this.state = null;
    return ev;
  }

  parseDocumentContent() {
    if (this.checkToken('directive', 'document-start', 'document-end', 'stream-end')) {
      const token = this.peekToken();
      const ev = this.processEmptyScalar(token.endMark);
      this.state = this.states.pop();
      return ev;
    }
    return this.parseBlockNode();
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = startMark;
    let explicitEnd = false;
    if (this.checkToken('document-end')) {
      token = this.getToken();
      endMark = token.endMark;
      explicitEnd = true;
    }
    const ev = event('document-end', { startMark, endMark, explicit: explicitEnd });
    this.state = () => this.parseImplicitDocumentStart();
    return ev;
  }

  parseBlockNode() {
    return this.parseNode(true, false);
  }

  parseFlowNode() {
    return this.parseNode(false, false);
  }

  parseBlockNodeOrIndentlessSequence() {
    return this.parseNode(true, true);
  }

  // node ::= ALIAS | properties content | content
  parseNode(block, indentlessSequence) {
    if (this.checkToken('alias')) {
      const token = this.getToken();
      const ev = event('alias', {
        anchor: token.value,
        startMark: token.startMark, endMark: token.endMark,
      });
      this.state = this.states.pop();
      return ev;
    }
    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    if (this.checkToken('anchor')) {
      let token = this.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.checkToken('tag')) {
        token = this.getToken();
        tagMark = token.startMark;
        endMark = token.endMark;
        tag = token.value;
      }
    } else if (this.checkToken('tag')) {
      let token = this.getToken();
      startMark = tagMark = token.startMark;
      endMark = token.endMark;
      tag = token.value;
      if (this.checkToken('anchor')) {
        token = this.getToken();
        startMark = token.startMark;
        endMark = token.endMark;
        anchor = token.value;
      }
    }
    if (tag !== null) {
      const [handle, suffix] = tag;
      if (handle !== null) {
        if (!(handle in this.tagHandles)) {
          throw new ParserError('while parsing a node', startMark,
            `found undefined tag handle '${handle}'`, tagMark);
        }
        tag = this.tagHandles[handle] + suffix;
      } else {
        tag = suffix;
      }
    }
    if (startMark === null) {
      startMark = endMark = this.peekToken().startMark;
    }
    let implicit = (tag === null || tag === '!');
    if (indentlessSequence && this.checkToken('block-entry')) {
      endMark = this.peekToken().endMark;
      const ev = event('sequence-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: false,
      });
      this.state = () => this.parseIndentlessSequenceEntry();
      return ev;
    }
    if (this.checkToken('scalar')) {
      const token = this.getToken();
      endMark = token.endMark;
      if ((token.plain && tag === null) || tag === '!') {
        implicit = [true, false];
      } else if (tag === null) {
        implicit = [false, true];
      } else {
        implicit = [false, false];
      }
      const ev = event('scalar', {
        anchor, tag, implicit, value: token.value,
        startMark, endMark, style: token.style,
      });
      this.state = this.states.pop();
      return ev;
    }
    if (this.checkToken('flow-sequence-start')) {
      endMark = this.peekToken().endMark;
      const ev = event('sequence-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: true,
      });
      this.state = () => this.parseFlowSequenceFirstEntry();
      return ev;
    }
    if (this.checkToken('flow-mapping-start')) {
      endMark = this.peekToken().endMark;
      const ev = event('mapping-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: true,
      });
      this.state = () => this.parseFlowMappingFirstKey();
      return ev;
    }
    if (block && this.checkToken('block-sequence-start')) {
      endMark = this.peekToken().startMark;
      const ev = event('sequence-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: false,
      });
      this.state = () => this.parseBlockSequenceFirstEntry();
      return ev;
    }
    if (block && this.checkToken('block-mapping-start')) {
      endMark = this.peekToken().startMark;
      const ev = event('mapping-start', {
        anchor, tag, implicit, startMark, endMark, flowStyle: false,
      });
      this.state = () => this.parseBlockMappingFirstKey();
      return ev;
    }
    if (anchor !== null || tag !== null) {
      // Empty scalars are allowed even if an anchor or a tag is specified.
      const ev = event('scalar', {
        anchor, tag, implicit: [implicit, false], value: '',
        startMark, endMark, style: null,
      });
      this.state = this.states.pop();
      return ev;
    }
    const node = block ? 'block' : 'flow';
    const token = this.peekToken();
    throw new ParserError(`while parsing a ${node} node`, startMark,
      `expected the node content, but found '${token.id}'`, token.startMark);
  }

  // block_sequence ::= BLOCK-SEQUENCE-START (BLOCK-ENTRY block_node?)* BLOCK-END
  parseBlockSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockSequenceEntry();
  }

  parseBlockSequenceEntry() {
    if (this.checkToken('block-entry')) {
      const token = this.getToken();
      if (!this.checkToken('block-entry', 'block-end')) {
        this.states.push(() => this.parseBlockSequenceEntry());
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = () => this.parseBlockSequenceEntry();
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('block-end')) {
      const token = this.peekToken();
      throw new ParserError('while parsing a block collection',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found '${token.id}'`, token.startMark);
    }
    const token = this.getToken();
    const ev = event('sequence-end', { startMark: token.startMark, endMark: token.endMark });
    this.state = this.states.pop();
    this.marks.pop();
    return ev;
  }

  // indentless_sequence ::= (BLOCK-ENTRY block_node?)+
  parseIndentlessSequenceEntry() {
    if (this.checkToken('block-entry')) {
      const token = this.getToken();
      if (!this.checkToken('block-entry', 'key', 'value', 'block-end')) {
        this.states.push(() => this.parseIndentlessSequenceEntry());
        return this.parseBlockNode();
      }
      this.state = () => this.parseIndentlessSequenceEntry();
      return this.processEmptyScalar(token.endMark);
    }
    const token = this.peekToken();
    const ev = event('sequence-end', { startMark: token.startMark, endMark: token.startMark });
    this.state = this.states.pop();
    return ev;
  }

  // block_mapping ::= BLOCK-MAPPING_START ((KEY block_node_or_indentless_sequence?)
  //                   (VALUE block_node_or_indentless_sequence?)?)* BLOCK-END
  parseBlockMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockMappingKey();
  }

  parseBlockMappingKey() {
    if (this.checkToken('key')) {
      const token = this.getToken();
      if (!this.checkToken('key', 'value', 'block-end')) {
        this.states.push(() => this.parseBlockMappingValue());
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = () => this.parseBlockMappingValue();
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('block-end')) {
      const token = this.peekToken();
      throw new ParserError('while parsing a block mapping',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found '${token.id}'`, token.startMark);
    }
    const token = this.getToken();
    const ev = event('mapping-end', { startMark: token.startMark, endMark: token.endMark });
    this.state = this.states.pop();
    this.marks.pop();
    return ev;
  }

  parseBlockMappingValue() {
    if (this.checkToken('value')) {
      const token = this.getToken();
      if (!this.checkToken('key', 'value', 'block-end')) {
        this.states.push(() => this.parseBlockMappingKey());
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = () => this.parseBlockMappingKey();
      return this.processEmptyScalar(token.endMark);
    }
    this.state = () => this.parseBlockMappingKey();
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  processEmptyScalar(mark) {
    return event('scalar', {
      anchor: null, tag: null, implicit: [true, false], value: '',
      startMark: mark, endMark: mark, style: null,
    });
  }

  // flow_sequence ::= FLOW-SEQUENCE-START (flow_sequence_entry FLOW-ENTRY)*
  //                   flow_sequence_entry? FLOW-SEQUENCE-END
  parseFlowSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowSequenceEntry(true);
  }

  parseFlowSequenceEntry(first = false) {
    if (!first) {
      if (this.checkToken('flow-entry')) {
        this.getToken();
      } else {
        const token = this.peekToken();
        throw new ParserError('while parsing a flow sequence',
          this.marks[this.marks.length - 1],
          `expected ',' or ']', but got '${token.id}'`, token.startMark);
      }
    }
    if (this.checkToken('key')) {
      const token = this.peekToken();
      const ev = event('mapping-start', {
        anchor: null, tag: null, implicit: true,
        startMark: token.startMark, endMark: token.endMark, flowStyle: true,
      });
      this.state = () => this.parseFlowSequenceEntryMappingKey();
      return ev;
    }
    if (!this.checkToken('flow-sequence-end')) {
      this.states.push(() => this.parseFlowSequenceEntry());
      return this.parseFlowNode();
    }
    const token = this.getToken();
    const ev = event('sequence-end', { startMark: token.startMark, endMark: token.endMark });
    this.state = this.states.pop();
    this.marks.pop();
    return ev;
  }

  parseFlowSequenceEntryMappingKey() {
    const token = this.getToken();
    if (!this.checkToken('value', 'flow-entry', 'flow-sequence-end')) {
      this.states.push(() => this.parseFlowSequenceEntryMappingValue());
      return this.parseFlowNode();
    }
    this.state = () => this.parseFlowSequenceEntryMappingValue();
    return this.processEmptyScalar(token.endMark);
  }

  parseFlowSequenceEntryMappingValue() {
    if (this.checkToken('value')) {
      const token = this.getToken();
      if (!this.checkToken('flow-entry', 'flow-sequence-end')) {
        this.states.push(() => this.parseFlowSequenceEntryMappingEnd());
        return this.parseFlowNode();
      }
      this.state = () => this.parseFlowSequenceEntryMappingEnd();
      return this.processEmptyScalar(token.endMark);
    }
    this.state = () => this.parseFlowSequenceEntryMappingEnd();
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  parseFlowSequenceEntryMappingEnd() {
    this.state = () => this.parseFlowSequenceEntry();
    const token = this.peekToken();
    return event('mapping-end', { startMark: token.startMark, endMark: token.startMark });
  }

  // flow_mapping ::= FLOW-MAPPING-START (flow_mapping_entry FLOW-ENTRY)*
  //                  flow_mapping_entry? FLOW-MAPPING-END
  parseFlowMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowMappingKey(true);
  }

  parseFlowMappingKey(first = false) {
    if (!first) {
      if (this.checkToken('flow-entry')) {
        this.getToken();
      } else {
        const token = this.peekToken();
        throw new ParserError('while parsing a flow mapping',
          this.marks[this.marks.length - 1],
          `expected ',' or '}', but got '${token.id}'`, token.startMark);
      }
    }
    if (this.checkToken('key')) {
      const token = this.getToken();
      if (!this.checkToken('value', 'flow-entry', 'flow-mapping-end')) {
        this.states.push(() => this.parseFlowMappingValue());
        return this.parseFlowNode();
      }
      this.state = () => this.parseFlowMappingValue();
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('flow-mapping-end')) {
      this.states.push(() => this.parseFlowMappingKey());
      return this.parseFlowNode();
    }
    const token = this.getToken();
    const ev = event('mapping-end', { startMark: token.startMark, endMark: token.endMark });
    this.state = this.states.pop();
    this.marks.pop();
    return ev;
  }

  parseFlowMappingValue() {
    if (this.checkToken('value')) {
      const token = this.getToken();
      if (!this.checkToken('flow-entry', 'flow-mapping-end')) {
        this.states.push(() => this.parseFlowMappingKey());
        return this.parseFlowNode();
      }
      this.state = () => this.parseFlowMappingKey();
      return this.processEmptyScalar(token.endMark);
    }
    this.state = () => this.parseFlowMappingKey();
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  // ------------------------------------------------------------------
  // Directives
  // ------------------------------------------------------------------

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = {};
    while (this.checkToken('directive')) {
      const token = this.getToken();
      if (token.name === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null,
            'found duplicate YAML directive', token.startMark);
        }
        const [major, minor] = token.value;
        if (major !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark);
        }
        this.yamlVersion = token.value;
      } else if (token.name === 'TAG') {
        const [handle, prefix] = token.value;
        if (handle in this.tagHandles) {
          throw new ParserError(null, null,
            `duplicate tag handle '${handle}'`, token.startMark);
        }
        this.tagHandles[handle] = prefix;
      }
    }
    let value;
    if (Object.keys(this.tagHandles).length > 0) {
      value = [this.yamlVersion, { ...this.tagHandles }];
    } else {
      value = [this.yamlVersion, null];
    }
    for (const key of Object.keys(DEFAULT_TAGS)) {
      if (!(key in this.tagHandles)) {
        this.tagHandles[key] = DEFAULT_TAGS[key];
      }
    }
    return value;
  }
}

