    this.anchors = new Map();
  }

  checkEvent(...types) { return this.parser.checkEvent(...types); }
  peekEvent() { return this.parser.peekEvent(); }
  getEvent() { return this.parser.getEvent(); }

  // Returns the single document's root node, or null for an empty stream.
  // Mirrors PyYAML's Composer.get_single_node + BaseConstructor.get_single_data.
  getSingleNode() {
    // Drop the STREAM-START event.
    this.getEvent();
    // Compose the root node of the first (and only) document.
    let node = null;
    if (!this.checkEvent('stream-end')) {
      node = this.composeDocument();
    }
    // Ensure that the stream contains a single document.
    if (!this.checkEvent('stream-end')) {
      const ev = this.getEvent();
      throw new ComposerError('expected a single document in the stream',
        node.startMark, 'but found another document', ev.startMark);
    }
    // Drop the STREAM-END event.
    this.getEvent();
    return node;
  }

  composeDocument() {
    // Drop the DOCUMENT-START event.
    this.getEvent();
    // Compose the root node.
    const node = this.composeNode(null, null);
    // Drop the DOCUMENT-END event.
    this.getEvent();
    this.anchors.clear();
    return node;
  }

  composeNode(parent, index) {
    if (this.checkEvent('alias')) {
      const ev = this.getEvent();
      const anchor = ev.anchor;
      if (!this.anchors.has(anchor)) {
        throw new ComposerError(null, null,
          `found undefined alias '${anchor}'`, ev.startMark);
      }
      return this.anchors.get(anchor);
    }
    const ev = this.peekEvent();
    const anchor = ev.anchor;
    if (anchor !== null && anchor !== undefined && this.anchors.has(anchor)) {
      throw new ComposerError(
        `found duplicate anchor '${anchor}'; first occurrence`,
        this.anchors.get(anchor).startMark, 'second occurrence', ev.startMark);
    }
    let node;
    if (this.checkEvent('scalar')) {
      node = this.composeScalarNode(anchor);
    } else if (this.checkEvent('sequence-start')) {
      node = this.composeSequenceNode(anchor);
    } else if (this.checkEvent('mapping-start')) {
      node = this.composeMappingNode(anchor);
    }
    return node;
  }

  composeScalarNode(anchor) {
    const ev = this.getEvent();
    let tag = ev.tag;
    if (tag === null || tag === '!') {
      tag = resolve('scalar', ev.value, ev.implicit);
    }
    const node = new ScalarNode(tag, ev.value, ev.startMark, ev.endMark, ev.style);
    if (anchor !== null && anchor !== undefined) {
      this.anchors.set(anchor, node);
    }
    return node;
  }

  composeSequenceNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = resolve('sequence', null, startEvent.implicit);
    }
    const node = new SequenceNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null && anchor !== undefined) {
      this.anchors.set(anchor, node);
    }
    let index = 0;
    while (!this.checkEvent('sequence-end')) {
      node.value.push(this.composeNode(node, index));
      index += 1;
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }

  composeMappingNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = resolve('mapping', null, startEvent.implicit);
    }
    const node = new MappingNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null && anchor !== undefined) {
      this.anchors.set(anchor, node);
    }
    while (!this.checkEvent('mapping-end')) {
      const itemKey = this.composeNode(node, node.value.length);
      const itemValue = this.composeNode(node, itemKey);
      node.value.push([itemKey, itemValue]);
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }
}

