// Object constructor: a port of PyYAML's constructor.py (BaseConstructor +
// SafeConstructor). Builds the JavaScript values documented in types.mjs
// from the composed node graph. Two-phase (generator) construction is kept
// so that recursive anchor/alias structures work exactly like PyYAML.

import { Buffer } from 'node:buffer';
import { YFloat, YTimestamp } from './types.mjs';
import { ConstructorError } from './errors.mjs';
import {
  STR_TAG, SEQ_TAG, MAP_TAG, NULL_TAG, BOOL_TAG, INT_TAG, FLOAT_TAG,
  BINARY_TAG, TIMESTAMP_TAG, MERGE_TAG, VALUE_TAG, SET_TAG, OMAP_TAG,
  PAIRS_TAG,
} from './resolver.mjs';

// Decoded !!binary payload. Not part of the shared types.mjs model (which
// has no binary type), so the loader wraps it here; see the report.
export class YBinary {
  // data: a Buffer with the decoded bytes.
  constructor(data) {
    this.data = data;
  }
}

// Loose base64 decoding matching Python's base64.decodebytes (non-alphabet
// characters such as newlines are ignored).
function decodeBase64(text, node) {
  const cleaned = text.replace(/[^A-Za-z0-9+/=]/g, '');
  try {
    return Buffer.from(cleaned, 'base64');
  } catch {
    throw new ConstructorError(null, null,
      `failed to decode base64 data: ${cleaned}`, node.startMark);
  }
}

// Timestamp constructor regexp with named groups (PyYAML's
// SafeConstructor.timestamp_regexp).
const TIMESTAMP_RE = /^(?<year>[0-9][0-9][0-9][0-9])-(?<month>[0-9][0-9]?)-(?<day>[0-9][0-9]?)(?:(?:[Tt]|[ \t]+)(?<hour>[0-9][0-9]?):(?<minute>[0-9][0-9]):(?<second>[0-9][0-9])(?:\.(?<fraction>[0-9]*))?(?:[ \t]*(?<tz>Z|(?<tzSign>[-+])(?<tzHour>[0-9][0-9]?)(?::(?<tzMinute>[0-9][0-9]))?))?)?$/;

const BOOL_VALUES = {
  yes: true, no: false,
  true: true, false: false,
  on: true, off: false,
};

function isGenerator(obj) {
  return obj !== null && typeof obj === 'object' &&
    typeof obj.next === 'function' && typeof obj[Symbol.iterator] === 'function';
}

function pad2(n) {
  return String(n).padStart(2, '0');
}

// Days in a month, for validating timestamps like Python's datetime.
function daysInMonth(year, month) {
  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

export class SafeConstructor {
  constructor() {
    this.constructedObjects = new Map();
    this.recursiveObjects = new Set();
    this.stateGenerators = [];
    this.deepConstruct = false;

    this.yamlConstructors = new Map([
      [NULL_TAG, this.constructYamlNull],
      [BOOL_TAG, this.constructYamlBool],
      [INT_TAG, this.constructYamlInt],
      [FLOAT_TAG, this.constructYamlFloat],
      [BINARY_TAG, this.constructYamlBinary],
      [TIMESTAMP_TAG, this.constructYamlTimestamp],
      [OMAP_TAG, this.constructYamlOmap],
      [PAIRS_TAG, this.constructYamlPairs],
      [SET_TAG, this.constructYamlSet],
      [STR_TAG, this.constructYamlStr],
      [SEQ_TAG, this.constructYamlSeq],
      [MAP_TAG, this.constructYamlMap],
      [null, this.constructUndefined],
    ]);
  }

  // ------------------------------------------------------------------
  // BaseConstructor machinery
  // ------------------------------------------------------------------

  constructDocument(node) {
    const data = this.constructObject(node);
    while (this.stateGenerators.length > 0) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const gen of generators) {
        while (!gen.next().done) { /* exhaust */ }
      }
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Set();
    this.deepConstruct = false;
    return data;
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) {
      return this.constructedObjects.get(node);
    }
    let oldDeep;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(null, null,
        'found unconstructable recursive node', node.startMark);
    }
    this.recursiveObjects.add(node);
    const ctor = this.yamlConstructors.has(node.tag)
      ? this.yamlConstructors.get(node.tag)
      : this.yamlConstructors.get(null);
    let data = ctor.call(this, node);
    if (isGenerator(data)) {
      const gen = data;
      data = gen.next().value;
      if (this.deepConstruct) {
        while (!gen.next().done) { /* exhaust */ }
      } else {
        this.stateGenerators.push(gen);
      }
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) {
      this.deepConstruct = oldDeep;
    }
    return data;
  }

  constructScalar(node) {
    if (node.kind === 'mapping') {
      // Special case: a mapping used as a scalar (YAML 'value' key idiom).
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === VALUE_TAG) {
          return this.constructScalar(valueNode);
        }
      }
    }
    if (node.kind !== 'scalar') {
      throw new ConstructorError(null, null,
        `expected a scalar node, but found ${node.kind}`, node.startMark);
    }
    return node.value;
  }

  constructSequence(node, deep = false) {
    if (node.kind !== 'sequence') {
      throw new ConstructorError(null, null,
        `expected a sequence node, but found ${node.kind}`, node.startMark);
    }
    return node.value.map((child) => this.constructObject(child, deep));
  }

  constructMapping(node, deep = false) {
    if (node.kind !== 'mapping') {
      throw new ConstructorError(null, null,
        `expected a mapping node, but found ${node.kind}`, node.startMark);
    }
    const mapping = {};
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, true);
      const skey = this.keyToString(key, node, keyNode);
      const value = this.constructObject(valueNode, deep);
      mapping[skey] = value;
    }
    return mapping;
  }

  // Mapping keys must become JS strings (types.mjs contract). Non-scalar
  // keys are unhashable in Python and raise like PyYAML does.
  keyToString(key, mapNode, keyNode) {
    if (typeof key === 'string') return key;
    if (key === null) return 'null';
    if (typeof key === 'boolean') return key ? 'true' : 'false';
    if (typeof key === 'number') return String(key);
    if (key instanceof YFloat) {
      const v = key.value;
      if (Number.isNaN(v)) return '.nan';
      if (v === Infinity) return '.inf';
      if (v === -Infinity) return '-.inf';
      if (Number.isInteger(v)) return v.toFixed(1);
      return String(v);
    }
    if (key instanceof YTimestamp) return key.text;
    throw new ConstructorError('while constructing a mapping',
      mapNode.startMark, 'found unhashable key', keyNode.startMark);
  }

  // Merge key ('<<') handling, port of SafeConstructor.flatten_mapping.
  flattenMapping(node) {
    const merge = [];
    let index = 0;
    while (index < node.value.length) {
      const [keyNode, valueNode] = node.value[index];
      if (keyNode.tag === MERGE_TAG) {
        node.value.splice(index, 1);
        if (valueNode.kind === 'mapping') {
          this.flattenMapping(valueNode);
          merge.push(...valueNode.value);
        } else if (valueNode.kind === 'sequence') {
          const submerge = [];
          for (const subnode of valueNode.value) {
            if (subnode.kind !== 'mapping') {
              throw new ConstructorError('while constructing a mapping',
                node.startMark,
                `expected a mapping for merging, but found ${subnode.kind}`,
                subnode.startMark);
            }
            this.flattenMapping(subnode);
            submerge.push(subnode.value);
          }
          submerge.reverse();
          for (const value of submerge) {
            merge.push(...value);
          }
        } else {
          throw new ConstructorError('while constructing a mapping',
            node.startMark,
            `expected a mapping or list of mappings for merging, but found ${valueNode.kind}`,
            valueNode.startMark);
        }
      } else if (keyNode.tag === VALUE_TAG) {
        keyNode.tag = STR_TAG;
        index += 1;
      } else {
        index += 1;
      }
    }
    if (merge.length > 0) {
      node.value = merge.concat(node.value);
    }
  }

  // ------------------------------------------------------------------
  // SafeConstructor constructors
  // ------------------------------------------------------------------

  constructUndefined(node) {
    throw new ConstructorError(null, null,
      `could not determine a constructor for the tag '${node.tag}'`,
      node.startMark);
  }

  constructYamlNull() {
    return null;
  }

  constructYamlBool(node) {
    const value = this.constructScalar(node);
    return BOOL_VALUES[value.toLowerCase()];
  }

  constructYamlInt(node) {
    let value = this.constructScalar(node).replace(/_/g, '');
    let sign = 1;
    if (value[0] === '-') {
      sign = -1;
    }
    if (value[0] === '-' || value[0] === '+') {
      value = value.slice(1);
    }
    if (value === '0') {
      return 0;
    }
    if (value.startsWith('0b')) {
      return sign * parseInt(value.slice(2), 2);
    }
    if (value.startsWith('0x')) {
      return sign * parseInt(value.slice(2), 16);
    }
    if (value[0] === '0') {
      return sign * parseInt(value, 8);
    }
    if (value.includes(':')) {
      // Sexagesimal (base-60) integer.
      const digits = value.split(':').map((part) => parseInt(part, 10));
      digits.reverse();
      let base = 1;
      let result = 0;
      for (const digit of digits) {
        result += digit * base;
        base *= 60;
      }
      return sign * result;
    }
    return sign * parseInt(value, 10);
  }

  constructYamlFloat(node) {
    let value = this.constructScalar(node).replace(/_/g, '').toLowerCase();
    let sign = 1;
    if (value[0] === '-') {
      sign = -1;
    }
    if (value[0] === '-' || value[0] === '+') {
      value = value.slice(1);
    }
    if (value === '.inf') {
      return new YFloat(sign * Infinity);
    }
    if (value === '.nan') {
      return new YFloat(NaN);
    }
    if (value.includes(':')) {
      // Sexagesimal (base-60) float.
      const digits = value.split(':').map((part) => parseFloat(part));
      digits.reverse();
      let base = 1;
      let result = 0.0;
      for (const digit of digits) {
        result += digit * base;
        base *= 60;
      }
      return new YFloat(sign * result);
    }
    return new YFloat(sign * parseFloat(value));
  }

  constructYamlBinary(node) {
    const value = this.constructScalar(node);
    // PyYAML rejects non-ASCII content in binary scalars.
    // eslint-disable-next-line no-control-regex
    if (/[^\x00-\x7F]/.test(value)) {
      throw new ConstructorError(null, null,
        'invalid base64-encoded data in binary scalar', node.startMark);
    }
    return new YBinary(decodeBase64(value, node));
  }

  constructYamlTimestamp(node) {
    const match = TIMESTAMP_RE.exec(node.value);
    const g = match.groups;
    const year = parseInt(g.year, 10);
    const month = parseInt(g.month, 10);
    const day = parseInt(g.day, 10);
    if (g.hour === undefined) {
      // Plain date: validate like datetime.date does.
      if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
        throw new ConstructorError(null, null,
          `invalid date '${node.value}'`, node.startMark);
      }
      return new YTimestamp(
        `${String(year).padStart(4, '0')}-${pad2(month)}-${pad2(day)}`);
    }
    const hour = parseInt(g.hour, 10);
    const minute = parseInt(g.minute, 10);
    const second = parseInt(g.second, 10);
    if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month) ||
        hour > 23 || minute > 59 || second > 59) {
      throw new ConstructorError(null, null,
        `invalid timestamp '${node.value}'`, node.startMark);
    }
    // Python's isoformat() emits microseconds (6 digits) only when nonzero;
    // the constructor zero-pads any fraction to 6 digits, so any fraction
    // present in the source produces a 6-digit fraction in the output.
    let fraction = '';
    if (g.fraction) {
      fraction = '.' + g.fraction.slice(0, 6).padEnd(6, '0');
    }
    let tz = '';
    if (g.tz === 'Z') {
      tz = '+00:00';
    } else if (g.tzSign) {
      const tzHour = parseInt(g.tzHour, 10);
      const tzMinute = g.tzMinute !== undefined ? parseInt(g.tzMinute, 10) : 0;
      if (tzHour > 23 || tzMinute > 59) {
        throw new ConstructorError(null, null,
          `invalid timestamp '${node.value}'`, node.startMark);
      }
      tz = `${g.tzSign}${pad2(tzHour)}:${pad2(tzMinute)}`;
    }
    const text = `${String(year).padStart(4, '0')}-${pad2(month)}-${pad2(day)}` +
      ` ${pad2(hour)}:${pad2(minute)}:${pad2(second)}${fraction}${tz}`;
    return new YTimestamp(text);
  }

  constructYamlStr(node) {
    return this.constructScalar(node);
  }

  *constructYamlSeq(node) {
    const data = [];
    yield data;
    data.push(...this.constructSequence(node));
  }

  *constructYamlMap(node) {
    const data = {};
    yield data;
    this.flattenMapping(node);
    Object.assign(data, this.constructMapping(node));
  }

  *constructYamlSet(node) {
    const data = {};
    yield data;
    Object.assign(data, this.constructMapping(node));
  }

  // Ordered maps and pairs: sequences of single-pair mappings. There is no
  // dedicated JS representation in the value model, so they become arrays
  // of single-key plain objects (matching the sequence-of-mappings shape).
  *constructYamlOmap(node) {
    const omap = [];
    yield omap;
    if (node.kind !== 'sequence') {
      throw new ConstructorError('while constructing an ordered map',
        node.startMark, `expected a sequence, but found ${node.kind}`,
        node.startMark);
    }
    for (const subnode of node.value) {
      if (subnode.kind !== 'mapping') {
        throw new ConstructorError('while constructing an ordered map',
          node.startMark,
          `expected a mapping of length 1, but found ${subnode.kind}`,
          subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError('while constructing an ordered map',
          node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark);
      }
      const [keyNode, valueNode] = subnode.value[0];
      const key = this.constructObject(keyNode);
      omap.push({ [this.keyToString(key, node, keyNode)]: this.constructObject(valueNode) });
    }
  }

  *constructYamlPairs(node) {
    const pairs = [];
    yield pairs;
    if (node.kind !== 'sequence') {
      throw new ConstructorError('while constructing pairs', node.startMark,
        `expected a sequence, but found ${node.kind}`, node.startMark);
    }
    for (const subnode of node.value) {
      if (subnode.kind !== 'mapping') {
        throw new ConstructorError('while constructing pairs', node.startMark,
          `expected a mapping of length 1, but found ${subnode.kind}`,
          subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError('while constructing pairs', node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark);
      }
      const [keyNode, valueNode] = subnode.value[0];
      const key = this.constructObject(keyNode);
      pairs.push({ [this.keyToString(key, node, keyNode)]: this.constructObject(valueNode) });
    }
  }
}

display.content:
// Object constructor: a port of PyYAML's constructor.py (BaseConstructor +
// SafeConstructor). Builds the JavaScript values documented in types.mjs
// from the composed node graph. Two-phase (generator) construction is kept
// so that recursive anchor/alias structures work exactly like PyYAML.

import { Buffer } from 'node:buffer';
import { YFloat, YTimestamp } from './types.mjs';
import { ConstructorError } from './errors.mjs';
import {
  STR_TAG, SEQ_TAG, MAP_TAG, NULL_TAG, BOOL_TAG, INT_TAG, FLOAT_TAG,
  BINARY_TAG, TIMESTAMP_TAG, MERGE_TAG, VALUE_TAG, SET_TAG, OMAP_TAG,
  PAIRS_TAG,
} from './resolver.mjs';

// Decoded !!binary payload. Not part of the shared types.mjs model (which
// has no binary type), so the loader wraps it here; see the report.
export class YBinary {
  // data: a Buffer with the decoded bytes.
  constructor(data) {
    this.data = data;
  }
}

// Loose base64 decoding matching Python's base64.decodebytes (non-alphabet
// characters such as newlines are ignored).
function decodeBase64(text, node) {
  const cleaned = text.replace(/[^A-Za-z0-9+/=]/g, '');
  try {
    return Buffer.from(cleaned, 'base64');
  } catch {
    throw new ConstructorError(null, null,
      `failed to decode base64 data: ${cleaned}`, node.startMark);
  }
}

// Timestamp constructor regexp with named groups (PyYAML's
// SafeConstructor.timestamp_regexp).
const TIMESTAMP_RE = /^(?<year>[0-9][0-9][0-9][0-9])-(?<month>[0-9][0-9]?)-(?<day>[0-9][0-9]?)(?:(?:[Tt]|[ \t]+)(?<hour>[0-9][0-9]?):(?<minute>[0-9][0-9]):(?<second>[0-9][0-9])(?:\.(?<fraction>[0-9]*))?(?:[ \t]*(?<tz>Z|(?<tzSign>[-+])(?<tzHour>[0-9][0-9]?)(?::(?<tzMinute>[0-9][0-9]))?))?)?$/;

const BOOL_VALUES = {
  yes: true, no: false,
  true: true, false: false,
  on: true, off: false,
};

function isGenerator(obj) {
  return obj !== null && typeof obj === 'object' &&
    typeof obj.next === 'function' && typeof obj[Symbol.iterator] === 'function';
}

function pad2(n) {
  return String(n).padStart(2, '0');
}

// Days in a month, for validating timestamps like Python's datetime.
function daysInMonth(year, month) {
  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

export class SafeConstructor {
  constructor() {
    this.constructedObjects = new Map();
    this.recursiveObjects = new Set();
    this.stateGenerators = [];
    this.deepConstruct = false;

    this.yamlConstructors = new Map([
      [NULL_TAG, this.constructYamlNull],
      [BOOL_TAG, this.constructYamlBool],
      [INT_TAG, this.constructYamlInt],
      [FLOAT_TAG, this.constructYamlFloat],
      [BINARY_TAG, this.constructYamlBinary],
      [TIMESTAMP_TAG, this.constructYamlTimestamp],
      [OMAP_TAG, this.constructYamlOmap],
      [PAIRS_TAG, this.constructYamlPairs],
      [SET_TAG, this.constructYamlSet],
      [STR_TAG, this.constructYamlStr],
      [SEQ_TAG, this.constructYamlSeq],
      [MAP_TAG, this.constructYamlMap],
      [null, this.constructUndefined],
    ]);
  }

  // ------------------------------------------------------------------
  // BaseConstructor machinery
  // ------------------------------------------------------------------

  constructDocument(node) {
    const data = this.constructObject(node);
    while (this.stateGenerators.length > 0) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const gen of generators) {
        while (!gen.next().done) { /* exhaust */ }
      }
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Set();
    this.deepConstruct = false;
    return data;
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) {
      return this.constructedObjects.get(node);
    }
    let oldDeep;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(null, null,
        'found unconstructable recursive node', node.startMark);
    }
    this.recursiveObjects.add(node);
    const ctor = this.yamlConstructors.has(node.tag)
      ? this.yamlConstructors.get(node.tag)
      : this.yamlConstructors.get(null);
    let data = ctor.call(this, node);
    if (isGenerator(data)) {
      const gen = data;
      data = gen.next().value;
      if (this.deepConstruct) {
        while (!gen.next().done) { /* exhaust */ }
      } else {
        this.stateGenerators.push(gen);
      }
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) {
      this.deepConstruct = oldDeep;
    }
    return data;
  }

  constructScalar(node) {
    if (node.kind === 'mapping') {
      // Special case: a mapping used as a scalar (YAML 'value' key idiom).
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === VALUE_TAG) {
          return this.constructScalar(valueNode);
        }
      }
    }
    if (node.kind !== 'scalar') {
      throw new ConstructorError(null, null,
        `expected a scalar node, but found ${node.kind}`, node.startMark);
    }
    return node.value;
  }

  constructSequence(node, deep = false) {
    if (node.kind !== 'sequence') {
      throw new ConstructorError(null, null,
        `expected a sequence node, but found ${node.kind}`, node.startMark);
    }
    return node.value.map((child) => this.constructObject(child, deep));
  }

  constructMapping(node, deep = false) {
    if (node.kind !== 'mapping') {
      throw new ConstructorError(null, null,
        `expected a mapping node, but found ${node.kind}`, node.startMark);
    }
    const mapping = {};
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, true);
      const skey = this.keyToString(key, node, keyNode);
      const value = this.constructObject(valueNode, deep);
      mapping[skey] = value;
    }
    return mapping;
  }

  // Mapping keys must become JS strings (types.mjs contract). Non-scalar
  // keys are unhashable in Python and raise like PyYAML does.
  keyToString(key, mapNode, keyNode) {
    if (typeof key === 'string') return key;
    if (key === null) return 'null';
    if (typeof key === 'boolean') return key ? 'true' : 'false';
    if (typeof key === 'number') return String(key);
    if (key instanceof YFloat) {
      const v = key.value;
      if (Number.isNaN(v)) return '.nan';
      if (v === Infinity) return '.inf';
      if (v === -Infinity) return '-.inf';
      if (Number.isInteger(v)) return v.toFixed(1);
      return String(v);
    }
    if (key instanceof YTimestamp) return key.text;
    throw new ConstructorError('while constructing a mapping',
      mapNode.startMark, 'found unhashable key', keyNode.startMark);
  }

  // Merge key ('<<') handling, port of SafeConstructor.flatten_mapping.
  flattenMapping(node) {
    const merge = [];
    let index = 0;
    while (index < node.value.length) {
      const [keyNode, valueNode] = node.value[index];
      if (keyNode.tag === MERGE_TAG) {
        node.value.splice(index, 1);
        if (valueNode.kind === 'mapping') {
          this.flattenMapping(valueNode);
          merge.push(...valueNode.value);
        } else if (valueNode.kind === 'sequence') {
          const submerge = [];
          for (const subnode of valueNode.value) {
            if (subnode.kind !== 'mapping') {
              throw new ConstructorError('while constructing a mapping',
                node.startMark,
                `expected a mapping for merging, but found ${subnode.kind}`,
                subnode.startMark);
            }
            this.flattenMapping(subnode);
            submerge.push(subnode.value);
          }
          submerge.reverse();
          for (const value of submerge) {
            merge.push(...value);
          }
        } else {
          throw new ConstructorError('while constructing a mapping',
            node.startMark,
            `expected a mapping or list of mappings for merging, but found ${valueNode.kind}`,
            valueNode.startMark);
        }
      } else if (keyNode.tag === VALUE_TAG) {
        keyNode.tag = STR_TAG;
        index += 1;
      } else {
        index += 1;
      }
    }
    if (merge.length > 0) {
      node.value = merge.concat(node.value);
    }
  }

  // ------------------------------------------------------------------
  // SafeConstructor constructors
  // ------------------------------------------------------------------

  constructUndefined(node) {
    throw new ConstructorError(null, null,
      `could not determine a constructor for the tag '${node.tag}'`,
      node.startMark);
  }

  constructYamlNull() {
    return null;
  }

  constructYamlBool(node) {
    const value = this.constructScalar(node);
    return BOOL_VALUES[value.toLowerCase()];
  }

  constructYamlInt(node) {
    let value = this.constructScalar(node).replace(/_/g, '');
    let sign = 1;
    if (value[0] === '-') {
      sign = -1;
    }
    if (value[0] === '-' || value[0] === '+') {
      value = value.slice(1);
    }
    if (value === '0') {
      return 0;
    }
    if (value.startsWith('0b')) {
      return sign * parseInt(value.slice(2), 2);
    }
    if (value.startsWith('0x')) {
      return sign * parseInt(value.slice(2), 16);
    }
    if (value[0] === '0') {
      return sign * parseInt(value, 8);
    }
    if (value.includes(':')) {
      // Sexagesimal (base-60) integer.
      const digits = value.split(':').map((part) => parseInt(part, 10));
      digits.reverse();
      let base = 1;
      let result = 0;
      for (const digit of digits) {
        result += digit * base;
        base *= 60;
      }
      return sign * result;
    }
    return sign * parseInt(value, 10);
  }

  constructYamlFloat(node) {
    let value = this.constructScalar(node).replace(/_/g, '').toLowerCase();
    let sign = 1;
    if (value[0] === '-') {
      sign = -1;
    }
    if (value[0] === '-' || value[0] === '+') {
      value = value.slice(1);
    }
    if (value === '.inf') {
      return new YFloat(sign * Infinity);
    }
    if (value === '.nan') {
      return new YFloat(NaN);
    }
    if (value.includes(':')) {
      // Sexagesimal (base-60) float.
      const digits = value.split(':').map((part) => parseFloat(part));
      digits.reverse();
      let base = 1;
      let result = 0.0;
      for (const digit of digits) {
        result += digit * base;
        base *= 60;
      }
      return new YFloat(sign * result);
    }
    return new YFloat(sign * parseFloat(value));
  }

  constructYamlBinary(node) {
    const value = this.constructScalar(node);
    // PyYAML rejects non-ASCII content in binary scalars.
    // eslint-disable-next-line no-control-regex
    if (/[^\x00-\x7F]/.test(value)) {
      throw new ConstructorError(null, null,
        'invalid base64-encoded data in binary scalar', node.startMark);
    }
    return new YBinary(decodeBase64(value, node));
  }

  constructYamlTimestamp(node) {
    const match = TIMESTAMP_RE.exec(node.value);
    const g = match.groups;
    const year = parseInt(g.year, 10);
    const month = parseInt(g.month, 10);
    const day = parseInt(g.day, 10);
    if (g.hour === undefined) {
      // Plain date: validate like datetime.date does.
      if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
        throw new ConstructorError(null, null,
          `invalid date '${node.value}'`, node.startMark);
      }
      return new YTimestamp(
        `${String(year).padStart(4, '0')}-${pad2(month)}-${pad2(day)}`);
    }
    const hour = parseInt(g.hour, 10);
    const minute = parseInt(g.minute, 10);
    const second = parseInt(g.second, 10);
    if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month) ||
        hour > 23 || minute > 59 || second > 59) {
      throw new ConstructorError(null, null,
        `invalid timestamp '${node.value}'`, node.startMark);
    }
    // Python's isoformat() emits microseconds (6 digits) only when nonzero;
    // the constructor zero-pads any fraction to 6 digits, so any fraction
    // present in the source produces a 6-digit fraction in the output.
    let fraction = '';
    if (g.fraction) {
      fraction = '.' + g.fraction.slice(0, 6).padEnd(6, '0');
    }
    let tz = '';
    if (g.tz === 'Z') {
      tz = '+00:00';
    } else if (g.tzSign) {
      const tzHour = parseInt(g.tzHour, 10);
      const tzMinute = g.tzMinute !== undefined ? parseInt(g.tzMinute, 10) : 0;
      if (tzHour > 23 || tzMinute > 59) {
        throw new ConstructorError(null, null,
          `invalid timestamp '${node.value}'`, node.startMark);
      }
      tz = `${g.tzSign}${pad2(tzHour)}:${pad2(tzMinute)}`;
    }
    const text = `${String(year).padStart(4, '0')}-${pad2(month)}-${pad2(day)}` +
      ` ${pad2(hour)}:${pad2(minute)}:${pad2(second)}${fraction}${tz}`;
    return new YTimestamp(text);
  }

  constructYamlStr(node) {
    return this.constructScalar(node);
  }

  *constructYamlSeq(node) {
    const data = [];
    yield data;
    data.push(...this.constructSequence(node));
  }

  *constructYamlMap(node) {
    const data = {};
    yield data;
    this.flattenMapping(node);
    Object.assign(data, this.constructMapping(node));
  }

  *constructYamlSet(node) {
    const data = {};
    yield data;
    Object.assign(data, this.constructMapping(node));
  }

  // Ordered maps and pairs: sequences of single-pair mappings. There is no
  // dedicated JS representation in the value model, so they become arrays
  // of single-key plain objects (matching the sequence-of-mappings shape).
  *constructYamlOmap(node) {
    const omap = [];
    yield omap;
    if (node.kind !== 'sequence') {
      throw new ConstructorError('while constructing an ordered map',
        node.startMark, `expected a sequence, but found ${node.kind}`,
        node.startMark);
    }
    for (const subnode of node.value) {
      if (subnode.kind !== 'mapping') {
        throw new ConstructorError('while constructing an ordered map',
          node.startMark,
          `expected a mapping of length 1, but found ${subnode.kind}`,
          subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError('while constructing an ordered map',
          node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark);
      }
      const [keyNode, valueNode] = subnode.value[0];
      const key = this.constructObject(keyNode);
      omap.push({ [this.keyToString(key, node, keyNode)]: this.constructObject(valueNode) });
    }
  }

  *constructYamlPairs(node) {
    const pairs = [];
    yield pairs;
    if (node.kind !== 'sequence') {
      throw new ConstructorError('while constructing pairs', node.startMark,
        `expected a sequence, but found ${node.kind}`, node.startMark);
    }
    for (const subnode of node.value) {
      if (subnode.kind !== 'mapping') {
        throw new ConstructorError('while constructing pairs', node.startMark,
          `expected a mapping of length 1, but found ${subnode.kind}`,
          subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError('while constructing pairs', node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark);
      }
      const [keyNode, valueNode] = subnode.value[0];
      const key = this.constructObject(keyNode);
      pairs.push({ [this.keyToString(key, node, keyNode)]: this.constructObject(valueNode) });
    }
  }
}

