args.command:
cat > /tmp/harness.mjs <<'EOF'
import { safeLoad, YBinary, YFloat, YTimestamp } from '/output/yaml/loader.mjs';

function floatRepr(v) {
  if (Number.isNaN(v)) return '.nan';
  if (v === Infinity) return '.inf';
  if (v === -Infinity) return '-.inf';
  if (Number.isInteger(v) && Math.abs(v) < 1e16) return v.toFixed(1);
  return String(v);
}

// Canonical serialization of the loaded value for comparison.
function canon(v) {
  if (v === null) return 'null';
  if (typeof v === 'boolean') return 'bool:' + v;
  if (typeof v === 'number') return 'int:' + v;
  if (typeof v === 'string') return 'str:' + JSON.stringify(v);
  if (v instanceof YFloat) return 'float:' + floatRepr(v.value);
  if (v instanceof YTimestamp) return 'ts:' + v.text;
  if (v instanceof YBinary) return 'bin:' + v.data.toString('base64');
  if (Array.isArray(v)) return '[' + v.map(canon).join(', ') + ']';
  if (typeof v === 'object') {
    const keys = Object.keys(v).sort();
    return '{' + keys.map(k => JSON.stringify(k) + '=' + canon(v[k])).join(', ') + '}';
  }
  return '???' + typeof v;
}

let pass = 0, fail = 0;
function ok(input, expected) {
  let got;
  try {
    got = canon(safeLoad(input));
  } catch (e) {
    got = 'ERROR:' + e.name + ': ' + e.message.split('\n')[0];
  }
  if (got === expected) { pass++; }
  else { fail++; console.log('FAIL', JSON.stringify(input)); console.log('  expected:', expected); console.log('  got:     ', got); }
}
function err(input, frag) {
  try {
    const v = safeLoad(input);
    fail++; console.log('FAIL(no-throw)', JSON.stringify(input), '->', canon(v), 'wanted error:', frag);
  } catch (e) {
    if (e.message.includes(frag)) pass++;
    else { fail++; console.log('FAIL(errmsg)', JSON.stringify(input)); console.log('  got:', e.message.split('\n').slice(0,3).join(' | ')); console.log('  wanted fragment:', frag); }
  }
}

// --- basic scalars / streams
ok('simple string', 'str:"simple string"');
ok('', 'null');
ok('# only a comment', 'null');
ok('---\n', 'null');
ok('null\n...\n', 'null');
ok('%YAML 1.1\n---\nfoo', 'str:"foo"');
ok('"quoted"', 'str:"quoted"');
ok('""', 'str:""');
ok("''", 'str:""');
ok("'it''s'", 'str:"it\'s"');
ok('plain\nmulti\nline scalar', 'str:"plain multi line scalar"');
ok('a: 1\r\nb: 2\r\n', '{"a"=int:1, "b"=int:2}');
ok('caf\u00e9 \u{1F600}', 'str:"caf\u00e9 \u{1F600}"');

// --- resolver: ints
ok('[1, 2.0, true, null, 0x1F, 1e3]',
