  // collections & nesting
  '[]', '{}', '[[]]', '[{}, []]', '-', '-\n- x', 'a: {}\nb: []',
  '- key: value\n  other: [1, 2]\n- - nested\n  - seq',
  'a:\n  b:\n    c: deep\n  d: [1, {e: f}]\ng: h',
  'mix: [1, {a: b}, [x, y], "q", \'s\', |]',
  // block scalars
  'x: |\n  a\n  b\n', 'x: |-\n  a\n\n\n', 'x: |+\n  a\n\n\ny: 1',
