  'x: |\n\n\n  a\n', 'x: | # comment\n  a\n',
  '- |\n  in seq\n- >\n  folded seq\n',
  // plain scalars
  'a: b: c', 'url: http://example.com/x?y=1', 'x: a#b', 'x: a #b',
  'key: value with spaces\nand lines\n  more indented\nend: done',
  // quoted
  '"multi\nline\nquoted"', "'multi\nline\nsingle'", '"tab\\there"',
  '"sp ace"', '"\\u00e9"', "'don''t'", '"it\'s"',
  // flow edge cases
  '[1,]', '{a: 1,}', '[,]', '{,}', '{? a: b}', '[? k : v]',
  '{a: , b: 2}', '[a, , b]', '{: v}', '[a:b]', '[a: b]',
  // anchors / aliases / tags
  '&a x', '!<!> x', '!!str x', '!!int 0x10', '!!float 1.5', '!!bool yes',
  '!!null whatever', 'a: &x [1, 2]\nb: *x', '&a {k: v}',
  '- &a 1\n- *a\n- &b [*a]\n- *b',
  '<<: {a: 1}\nb: 2',
  // merge variants
  'base: &b {x: 1, y: 2}\nderived:\n  <<: *b\n  y: 3',
  'a: &a {x: 1}\nb: &b {y: 2}\nc: {<<: [*a, *b], z: 3}',
  // implicit typing
  '[true, True, FALSE, Off, ON, n, N, y, No]', '[~, null, NULL, Null, ""]',
  '[0, -0, +0, 00, 0o0, 0x0, 0b0]', '[123_456, 0xff_FF, 0o777, 0b10_10]',
  '[1.0, -1.5, +.5, 5., .5e+1, 1.5E+10, -2.3e-4]', '[.INF, -.Inf, .NaN, .NAN]',
  '[1:2, 1:2:3, -1:30, 99:59:59]', '[1:60]', '[60:00]',
  '[2012-12-24, 2001-12-15 2:59:43, 2001-12-15t02:59:43Z]',
  '[2001-12-15 02:59:43.123456789, 2001-12-15 02:59:43 +00:00]',
  // documents
  '--- x\n', '---\nx: 1\n...\n', '... x\n', '%YAML 1.2\n---\nx',
  '%TAG !e! tag:ex.com,2020:\n---\n!e!thing [1]',
  // comments & blank lines
  '\n\n\n', '# c1\n# c2\n\nx: 1 # trailing\n\n# end\n',
  'a: 1\n\n\nb: 2\n\n',
  // errors
  '---\na\n---\nb', 'a: 1\n  b: 2', ':\nx', '?\n:', '- ]', '[1, 2',
  '{a: 1', '"unclosed', "'unclosed", 'x: "bad\\qescape"', '*missing',
  '&a 1\n&a 2', '!unknown x', 'x:\n y: 1\n  z: 2', '\ttab: 1',
  '2001-13-01', '2001-02-30', 'a: =', '...',
  '[1, 2}', '{a: 1]', 'x: |0\n  a\n', '!!str', '%YAML 2.0\n---\nx',
];

let agree = 0, disagree = 0;
for (const input of corpus) {
  let execOut = null, execErr = false;
  try {
    execOut = execFileSync('/workspace/dataset/test16_executable', ['--a=' + input],
      { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] });
  } catch { execErr = true; }
  let myVal = null, myErr = null;
  try { myVal = safeLoad(input); } catch (e) { myErr = e; }

  if (execErr || myErr) {
    if (execErr && myErr) { agree++; }
    else {
      disagree++;
      console.log('EXIT-DISAGREE', JSON.stringify(input),
        'exec:', execErr ? 'error' : JSON.stringify(execOut),
        'mine:', myErr ? (myErr.name + ': ' + myErr.message.split('\n')[0]) : canon(myVal));
    }
    continue;
  }
  // Both loaded: compare by re-loading the executable's dump.
  let roundtrip;
  try { roundtrip = canon(safeLoad(execOut)); }
  catch (e) { roundtrip = 'RELOAD-ERR: ' + e.message.split('\n')[0]; }
  const mine = canon(myVal);
  if (mine === roundtrip) { agree++; }
  else {
    disagree++;
    console.log('VALUE-DISAGREE', JSON.stringify(input));
    console.log('  exec dump:', JSON.stringify(execOut));
    console.log('  mine:     ', mine);
    console.log('  roundtrip:', roundtrip);
  }
}
console.log(`\n${agree} agree, ${disagree} disagree`);
